from datetime import datetime
from uuid import UUID

from sqlalchemy import Boolean, DateTime, String, Uuid, func, true
from sqlalchemy.orm import Mapped, mapped_column

from src.infrastructure.database.postgres.base import Base


class UserModel(Base):
    """Table layout for users. Kept apart from the domain User so schema changes
    (indexes, column names, types) never leak into business code."""

    __tablename__ = "users"

    # Ids are generated by the domain (uuid4), so the database does not supply a default.
    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True)
    # 320 = 64 (local part) + 1 (@) + 255 (domain), the RFC 5321 maximum.
    email: Mapped[str] = mapped_column(String(320), unique=True, index=True)
    hashed_password: Mapped[str] = mapped_column(String(255))
    full_name: Mapped[str] = mapped_column(String(255))
    is_active: Mapped[bool] = mapped_column(Boolean, server_default=true())
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
